mapper.select:
SELECT s.id, s.tag_id, t.name AS tag_name, t.parent_id, p.name AS parent_name, t.is_tech_stack, t.show_in_tech_map, s.level
FROM skill s
JOIN tag t ON s.tag_id = t.id
LEFT JOIN tag p ON t.parent_id = p.id
ORDER BY ${sortField} ${sortOrder}
LIMIT #{offset}, #{size}

mapper.update:
UPDATE skill
SET tag_id = #{tagId},
    level  = #{level}
WHERE id = #{id}
